{
 "permissions": {
  "allow": [
   "Edit(//Users/<you>/.codex/**)",
   "Write(//Users/<you>/.codex/**)",
   "Edit(//Users/<you>/.agents/**)",
   "Write(//Users/<you>/.agents/**)",
   "Bash(claude mcp list)",
   "Bash(mkdir *)",
   "Bash(git add *)"
  ],
  "defaultMode": "acceptEdits"
 },
 "hooks": {
  "SessionStart": [
   {
    "matcher": "^(startup|resume|clear|compact|fork)$",
    "hooks": [
     {
      "type": "command",
      "command": "bash '/Users/<you>/.claude/hooks/herdr-agent-state.sh' session",
      "timeout": 10
     }
    ]
   },
   {
    "matcher": "^(resume|compact)$",
    "hooks": [
     {
      "type": "command",
      "command": "/usr/bin/python3 /Users/<you>/.agents/tools/guards/chat_guard.py start",
      "timeout": 20
     }
    ]
   }
  ],
  "UserPromptSubmit": [
   {
    "hooks": [
     {
      "type": "command",
      "command": "/usr/bin/python3 /Users/<you>/.agents/tools/guards/chat_guard.py prompt",
      "timeout": 20
     }
    ]
   }
  ],
  "PreToolUse": [
   {
    "matcher": "Bash",
    "hooks": [
     {
      "type": "command",
      "command": "/usr/bin/python3 /Users/<you>/.agents/tools/guards/composio_guard.py",
      "if": "Bash(*composio*)",
      "timeout": 30
     }
    ]
   },
   {
    "matcher": "mcp__.*",
    "hooks": [
     {
      "type": "command",
      "command": "/usr/bin/python3 /Users/<you>/.agents/tools/guards/composio_guard.py",
      "timeout": 30
     }
    ]
   },
   {
    "matcher": "Agent|Task|Workflow",
    "hooks": [
     {
      "type": "command",
      "command": "/usr/bin/python3 /Users/<you>/.agents/tools/guards/chat_guard.py pre",
      "timeout": 20
     }
    ]
   }
  ],
  "PostToolUse": [
   {
    "matcher": "*",
    "hooks": [
     {
      "type": "command",
      "command": "/usr/bin/python3 /Users/<you>/.agents/tools/guards/chat_guard.py post",
      "timeout": 20
     }
    ]
   }
  ]
 },
 "enabledPlugins": {
  "composio@composio": true,
  "superpowers@claude-plugins-official": false
 },
 "extraKnownMarketplaces": {
  "composio": {
   "source": {
    "source": "git",
    "url": "https://github.com/ComposioHQ/composio-plugin-cc.git",
    "ref": "v0.2.4"
   }
  }
 },
 "sandbox": {
  "enabled": true,
  "allowUnsandboxedCommands": true
 },
 "autoMode": {
  "allow": [
   "$defaults",
   "Create, update, publish or delete GHL workflows, conversation/SMS AI agents and their prompts, voice agents and their prompts, voice/conversation actions, custom values, custom fields, tags, pipelines, calendars, forms and knowledge-base entries via the Composio toolkits custom_ghl_oauth_crm (CRM, tools CUSTOM_GHL_OAUTH_CRM_*) or custom_ghl_command_builder (builds, tools CUSTOM_GHL_COMMAND_BUILDER_*), called through the Composio connector or `composio execute`, when the user's request or an approved handoff/plan in this session covers the change, including live customer-facing bots.",
   "Delete a single GHL object (action, agent, workflow, field, value, tag) by ID when the user named the cleanup or approved a plan that lists it."
  ],
  "soft_deny": [
   "$defaults",
   "Sending SMS, email or calls to real GHL contacts, bulk-deleting contacts, or deleting a whole GHL sub-account, unless the user asked for that specific send or delete in this session."
  ],
  "environment": [
   "$defaults",
   "The user runs a GoHighLevel (GHL) agency. GHL sub-accounts reached through the Composio toolkits custom_ghl_oauth_crm and custom_ghl_command_builder (tools CUSTOM_GHL_OAUTH_CRM_* and CUSTOM_GHL_COMMAND_BUILDER_*) are the user's own or client accounts they are paid to manage; they are trusted work targets, not third-party systems.",
   "Editing GHL workflows, conversation/SMS agents, voice agents, voice actions, custom values, custom fields, tags, pipelines, calendars, forms and knowledge bases is the user's routine daily work."
  ]
 }
}
